1	// Roster's own model calls, on DeepSeek's OpenAI-compatible API. Never a Claude API
2	// (DESIGN.md §"Models Roster itself uses"). Retries 429/5xx twice with backoff (§"Recovery").
3	import OpenAI from "openai";
4	import { traceOpenAI, withSpan } from "../obs/index.ts";
5	import { priceDeepSeek } from "../price/deepseek.ts";
6	import { priceSession } from "../price/index.ts";
7	import {
8	  type ChatMessage,
9	  type ChatRequest,
10	  type ChatResult,
11	  type ChatUsage,
12	  DEEPSEEK_BASE_URL,
13	  DEFAULT_MODEL,
14	  type LlmClient,
15	  type ToolCall,
16	} from "./types.ts";
17	
18	export * from "./types.ts";
