20	/** The slice of an OpenAI-style chat completion response the client reads. */
21	export interface RawCompletion {
22	  model: string;
23	  choices: {
24	    message: {
25	      content: string | null;
26	      tool_calls?: (
27	        | { id: string; type: "function"; function: { name: string; arguments: string } }
28	        | { id: string; type: "custom"; custom: { name: string; input: string } }
29	      )[];
30	    };
31	  }[];
32	  usage?: {
33	    prompt_tokens: number;
34	    completion_tokens: number;
35	    prompt_tokens_details?: { cached_tokens?: number } | null;
36	    /** DeepSeek's own cache counters. */
37	    prompt_cache_hit_tokens?: number;
38	    prompt_cache_miss_tokens?: number;
39	  };
40	}
41	
42	/** Sends one chat completion request. The default goes through the `openai` package. */
43	export type Transport = (body: Record<string, unknown>) => Promise<RawCompletion>;
44	
45	export interface DeepSeekOptions {
46	  /** Default: env DEEPSEEK_API_KEY. */
47	  apiKey?: string;
48	  baseURL?: string;
49	  /** Default: env ROSTER_LLM_MODEL, else DEFAULT_MODEL. */
50	  model?: string;
51	  /** Retries on 429/5xx only. Default 2. */
52	  maxRetries?: number;
53	  /** First backoff delay; doubles per retry. Default 1000. */
54	  retryBaseMs?: number;
55	  sleep?: (ms: number) => Promise<void>;
56	  /** Replaces the network call. Tests use it; production leaves it unset. */
57	  transport?: Transport;
58	  /** The clock DeepSeek's time-of-day price is read from. Default: the time each response arrives. */
59	  now?: () => Date;
60	}
61	
62	/** The model a call uses when the request names none. */
63	export function defaultModel(): string {
64	  return process.env.ROSTER_LLM_MODEL || DEFAULT_MODEL;
65	}
66	
67	/** HTTP status carried by an SDK or fetch error, else null. */
68	export function errorStatus(err: unknown): number | null {
69	  if (typeof err === "object" && err !== null && "status" in err) {
70	    const s = (err as { status: unknown }).status;
71	    if (typeof s === "number") return s;
72	  }
73	  return null;
74	}
75	
76	/** True for the failures worth retrying: rate limits and server errors. */
77	export function isRetryable(err: unknown): boolean {
78	  const s = errorStatus(err);
79	  return s !== null && (s === 429 || s >= 500);
80	}
