82	function toWire(m: ChatMessage): Record<string, unknown> {
83	  if (m.role !== "assistant" || !m.tool_calls?.length) return { ...m };
84	  return {
85	    role: "assistant",
86	    content: m.content,
87	    tool_calls: m.tool_calls.map((c) => ({ id: c.id, type: "function", function: { name: c.name, arguments: c.arguments } })),
88	  };
89	}
