91	/**
92	 * Maps a raw completion to a ChatResult, priced for its model. Given `at` (when the call was answered), a DeepSeek
93	 * model is priced by priceDeepSeek's time-of-day rows, trying the answering model and then `requestedModel`.
94	 * Anything else goes through src/price, which holds no DeepSeek row, so DeepSeek without `at` stays unpriced.
95	 */
96	export function toResult(raw: RawCompletion, at?: Date, requestedModel?: string): ChatResult {
97	  const msg = raw.choices[0]?.message ?? { content: null };
98	  const toolCalls: ToolCall[] = (msg.tool_calls ?? []).map((c) =>
99	    c.type === "function"
100	      ? { id: c.id, name: c.function.name, arguments: c.function.arguments }
101	      : { id: c.id, name: c.custom.name, arguments: c.custom.input },
102	  );
103	  const u = raw.usage;
104	  const cached = u?.prompt_cache_hit_tokens ?? u?.prompt_tokens_details?.cached_tokens ?? 0;
105	  const usage: ChatUsage = {
106	    promptTokens: u?.prompt_tokens ?? 0,
107	    cachedPromptTokens: cached,
108	    completionTokens: u?.completion_tokens ?? 0,
109	  };
110	  let costUsd: number | null = null;
111	  if (u) {
112	    const tokens = {
113	      input: u.prompt_cache_miss_tokens ?? usage.promptTokens - cached,
114	      output: usage.completionTokens,
115	      cache_read: cached,
116	      prompt_tokens: usage.promptTokens,
117	    };
118	    const deepseek = at
119	      ? (priceDeepSeek(raw.model, tokens, at) ?? (requestedModel ? priceDeepSeek(requestedModel, tokens, at) : null))
120	      : null;
121	    costUsd = deepseek ? deepseek.usd : priceSession(raw.model, tokens).usd;
122	  }
123	  return {
124	    message: { role: "assistant", content: msg.content, ...(toolCalls.length ? { tool_calls: toolCalls } : {}) },
125	    toolCalls,
126	    usage,
127	    costUsd,
128	    model: raw.model,
129	  };
130	}
