132	/** A client for DeepSeek's chat completions. Throws when no API key is configured and no transport is given. */
133	export function deepseekClient(opts: DeepSeekOptions = {}): LlmClient {
134	  const maxRetries = opts.maxRetries ?? 2;
135	  const baseMs = opts.retryBaseMs ?? 1000;
136	  const sleep = opts.sleep ?? ((ms: number) => Bun.sleep(ms));
137	  const now = opts.now ?? (() => new Date());
138	  let transport = opts.transport;
139	  if (!transport) {
140	    const apiKey = opts.apiKey ?? process.env.DEEPSEEK_API_KEY;
141	    if (!apiKey) throw new Error("DEEPSEEK_API_KEY is not set; Roster's own model calls go to DeepSeek");
142	    // The SDK's own retries are off: ours are numbered and traced.
143	    const sdk = new OpenAI({ apiKey, baseURL: opts.baseURL ?? DEEPSEEK_BASE_URL, maxRetries: 0 });
144	    // Wrapped per call: the CLI builds this client before initObs runs, and traceOpenAI is a no-op until tracing is on.
145	    transport = (body) => traceOpenAI(sdk).chat.completions.create(body as never) as Promise<RawCompletion>;
146	  }
147	  const send = transport;
148	
149	  return {
150	    async chat(req: ChatRequest): Promise<ChatResult> {
151	      const body: Record<string, unknown> = {
152	        model: req.model ?? opts.model ?? defaultModel(),
153	        messages: req.messages.map(toWire),
154	      };
155	      if (req.temperature !== undefined) body.temperature = req.temperature;
156	      if (req.tools?.length) {
157	        body.tools = req.tools.map((t) => ({
158	          type: "function",
159	          function: { name: t.name, description: t.description, parameters: t.parameters },
160	        }));
161	      }
162	      for (let attempt = 1; ; attempt++) {
163	        try {
164	          const model = body.model as string;
165	          if (attempt === 1) return toResult(await send(body), now(), model);
166	          // Retries are a recovery path, so each one is a TOOL span carrying roster.attempt.
167	          return await withSpan("TOOL", "llm retry", { attempt }, async () => toResult(await send(body), now(), model));
168	        } catch (err) {
169	          if (!isRetryable(err) || attempt > maxRetries) throw err;
170	          await sleep(baseMs * 2 ** (attempt - 1));
171	        }
172	      }
173	    },
174	  };
175	}
