177	/** One scripted reply: a partial result, a function of the request, or an error to throw. */
178	export type FakeStep =
179	  | { content?: string | null; toolCalls?: ToolCall[]; costUsd?: number | null; usage?: Partial<ChatUsage>; model?: string }
180	  | ((req: ChatRequest) => FakeStep)
181	  | Error;
182	
183	export interface FakeClient extends LlmClient {
184	  /** Every request received, in order. */
185	  requests: ChatRequest[];
186	}
187	
188	/** A scripted client for tests. Each chat() consumes one step; running out throws. */
189	export function fakeClient(steps: FakeStep[]): FakeClient {
190	  const queue = [...steps];
191	  const requests: ChatRequest[] = [];
192	  return {
193	    requests,
194	    async chat(req) {
195	      requests.push(structuredClone(req));
196	      let step = queue.shift();
197	      if (step === undefined) throw new Error("fake LLM client: script exhausted");
198	      while (typeof step === "function") step = step(req);
199	      if (step instanceof Error) throw step;
200	      const toolCalls = step.toolCalls ?? [];
201	      return {
202	        message: { role: "assistant", content: step.content ?? null, ...(toolCalls.length ? { tool_calls: toolCalls } : {}) },
203	        toolCalls,
204	        usage: { promptTokens: 0, cachedPromptTokens: 0, completionTokens: 0, ...step.usage },
205	        costUsd: step.costUsd === undefined ? 0 : step.costUsd,
206	        model: step.model ?? req.model ?? "fake",
207	      };
208	    },
209	  };
210	}
