213	/** A tool call for a fake script. Pass a string to script malformed JSON arguments. */
214	export function fakeToolCall(name: string, args: Record<string, unknown> | string = {}): ToolCall {
215	  return { id: `call_${++fakeIds}`, name, arguments: typeof args === "string" ? args : JSON.stringify(args) };
216	}
