1	// The coordinator: a tool-calling loop on src/llm (DESIGN.md §"Plan (coordinator)", §"Coordinator tools", §"Recovery").
2	// It plans, replays, reads the gate and decides the next action until a candidate is promoted, it gives up honestly,
3	// or it hits budget_usd (LLM cost plus replay cost) or MAX_TURNS. Every step is appended to the `events` table in
4	// .roster/roster.db, and a run with the same id resumes from there.
5	import { Database } from "bun:sqlite";
6	import { mkdirSync, writeFileSync } from "node:fs";
7	import { dirname, join } from "node:path";
8	import { ATTR } from "../obs/attributes.ts";
9	import { withSpan } from "../obs/index.ts";
10	import type { ChatMessage, LlmClient } from "../llm/types.ts";
11	import type { Plan } from "../types.ts";
12	import { planFile, writePlanFile } from "./plan.ts";
13	import {
14	  type Decision,
15	  executeToolCall,
16	  initialState,
17	  planId,
18	  type RunState,
19	  TOOL_SPECS,
20	  type ToolBackend,
21	  type ToolContext,
22	} from "./tools.ts";
23	
24	export const MAX_TURNS = 40;
25	export const DEFAULT_DB = ".roster/roster.db";
26	
27	export const SYSTEM_PROMPT = `You are Roster's coordinator. Roster runs performance reviews for AI coding agents: it replays past tasks under the incumbent setup and candidate setups, grades them, and lets a deterministic gate decide promotion.
28	
29	You decide what to try next. The gate decides what ships. Never claim a result the tools didn't return.
30	
31	How to work:
32	- Read the scorecard, then call plan_replays with a one-paragraph rationale, the suspect setup, at most 3 candidates and at most 12 tasks.
33	- Replay the incumbent (as the control) and the candidates with run_replays, inspect results, rerun disagreements, and classify failures.
34	- Call gate for a candidate. If it promotes, call promote. If it rejects, replan with plan_replays and try the next candidate.
35	- If a task hits F6 (environment error), replan with a resampled task set.
36	- If no candidate passes, finish with outcome "no_better_setup". That is a valid result.
37	- The budget is a hard stop. Every tool answers with JSON; {"ok":false} means the call failed and you must not treat it as a result.`;
38	
39	export type StopReason = "promoted" | "no_better_setup" | "budget" | "max_turns" | "stopped" | "llm_error";
40	
41	/** Outcomes after which resuming does nothing more. */
42	const FINAL: ReadonlySet<StopReason> = new Set(["promoted", "no_better_setup", "stopped"]);
43	
44	export interface RunResult {
45	  runId: string;
46	  outcome: StopReason;
47	  promoted: string | null;
48	  summary: string;
49	  turns: number;
50	  llmUsd: number;
51	  replayUsd: number;
52	  spentUsd: number;
53	  /** LLM calls src/price could not price; their cost is not in llmUsd. */
54	  unpricedLlmCalls: number;
55	  decisions: Decision[];
56	  planPath: string | null;
57	  decisionsPath: string;
58	  resumed: boolean;
59	}
