61	export interface CoordinatorOptions {
62	  repo: string;
63	  budgetUsd: number;
64	  llm: LlmClient;
65	  backend: ToolBackend;
66	  /** Where plan.json and decisions.json go. */
67	  outDir: string;
68	  /** Default DEFAULT_DB. */
69	  dbPath?: string;
70	  /** Resume this run when its events exist; otherwise start it under this id. */
71	  runId?: string;
72	  reviewId?: string;
73	  model?: string;
74	  temperature?: number;
75	  maxTurns?: number;
76	  now?: () => Date;
77	}
