85	/** The append-only step log plus the plans and gate_decisions tables (DESIGN.md §"Data model"). */
86	export class EventStore {
87	  readonly db: Database;
88	
89	  constructor(path: string) {
90	    if (path !== ":memory:") mkdirSync(dirname(path), { recursive: true });
91	    this.db = new Database(path, { create: true });
92	    this.db.exec("PRAGMA journal_mode = WAL");
93	    this.db.exec(`CREATE TABLE IF NOT EXISTS events (
94	      id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, seq INTEGER NOT NULL, kind TEXT NOT NULL,
95	      payload TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (run_id, seq))`);
96	    this.db.exec(`CREATE TABLE IF NOT EXISTS plans (
97	      id TEXT PRIMARY KEY, review_id TEXT NOT NULL, json TEXT NOT NULL, rationale TEXT NOT NULL, created_at TEXT NOT NULL)`);
98	    this.db.exec(`CREATE TABLE IF NOT EXISTS gate_decisions (
99	      id TEXT PRIMARY KEY, plan_id TEXT NOT NULL, candidate TEXT NOT NULL, verdict TEXT NOT NULL,
100	      reasons TEXT NOT NULL, trace_url TEXT)`);
101	  }
102	
103	  events(runId: string): StoredEvent[] {
104	    return this.db
105	      .query<{ seq: number; kind: StoredEvent["kind"]; payload: string }, [string]>(
106	        "SELECT seq, kind, payload FROM events WHERE run_id = ? ORDER BY seq",
107	      )
108	      .all(runId)
109	      .map((r) => ({ seq: r.seq, kind: r.kind, payload: JSON.parse(r.payload) }));
110	  }
111	
112	  append(runId: string, kind: StoredEvent["kind"], payload: Record<string, unknown>, at: Date): void {
113	    const row = this.db.query<{ n: number | null }, [string]>("SELECT MAX(seq) AS n FROM events WHERE run_id = ?").get(runId);
114	    this.db
115	      .query("INSERT INTO events (run_id, seq, kind, payload, created_at) VALUES (?, ?, ?, ?, ?)")
116	      .run(runId, (row?.n ?? 0) + 1, kind, JSON.stringify(payload), at.toISOString());
117	  }
118	
119	  savePlan(plan: Plan): void {
120	    this.db
121	      .query("INSERT OR REPLACE INTO plans (id, review_id, json, rationale, created_at) VALUES (?, ?, ?, ?, ?)")
122	      .run(plan.id, plan.review_id, plan.json, plan.rationale, plan.created_at);
123	  }
124	
125	  saveDecision(d: Decision): void {
126	    this.db
127	      .query("INSERT OR REPLACE INTO gate_decisions (id, plan_id, candidate, verdict, reasons, trace_url) VALUES (?, ?, ?, ?, ?, ?)")
128	      .run(`${d.plan_id}:${d.candidate}`, d.plan_id, d.candidate, d.verdict, JSON.stringify(d.reasons), d.trace_url);
129	  }
130	
131	  close(): void {
132	    this.db.close();
133	  }
134	}
