136	/** Rebuilds a run from its events: the conversation, the last state snapshot and the LLM spend. */
137	function rebuild(events: StoredEvent[]) {
138	  const messages: ChatMessage[] = [];
139	  let state = initialState();
140	  let llmUsd = 0;
141	  let unpriced = 0;
142	  let turns = 0;
143	  let ended: RunResult | null = null;
144	  for (const e of events) {
145	    const p = e.payload;
146	    if (Array.isArray(p.messages)) messages.push(...(p.messages as ChatMessage[]));
147	    if (p.message) messages.push(p.message as ChatMessage);
148	    if (p.state) state = p.state as RunState;
149	    if (e.kind === "llm") {
150	      turns++;
151	      if (typeof p.costUsd === "number") llmUsd += p.costUsd;
152	      else unpriced++;
153	    }
154	    ended = e.kind === "end" ? (p.result as RunResult) : null;
155	  }
156	  return { messages, state, llmUsd, unpriced, turns, ended };
157	}
158	
159	/** A fresh run id, e.g. "run-20261010143000-k3x9". */
160	export const newRunId = (now: Date) =>
161	  `run-${now.toISOString().replace(/\D/g, "").slice(0, 14)}-${Math.random().toString(36).slice(2, 6)}`;
162	
163	/** Runs (or resumes) the coordinator until promotion, an honest give-up, the budget or MAX_TURNS. */
164	export async function runCoordinator(opts: CoordinatorOptions): Promise<RunResult> {
165	  const now = opts.now ?? (() => new Date());
166	  const maxTurns = opts.maxTurns ?? MAX_TURNS;
167	  const store = new EventStore(opts.dbPath ?? DEFAULT_DB);
168	  const runId = opts.runId ?? newRunId(now());
169	  const reviewId = opts.reviewId ?? runId;
170	  try {
171	    const prior = store.events(runId);
172	    const resumed = prior.length > 0;
173	    let { messages, state, llmUsd, unpriced, turns, ended } = rebuild(prior);
174	    if (ended && FINAL.has(ended.outcome)) return { ...ended, resumed: true };
175	
176	    const log = (kind: StoredEvent["kind"], payload: Record<string, unknown>) => store.append(runId, kind, payload, now());
177	    if (!resumed) {
178	      const start: ChatMessage[] = [
179	        { role: "system", content: SYSTEM_PROMPT },
180	        {
181	          role: "user",
182	          content: `Review ${opts.repo}. Run id ${runId}. Budget $${opts.budgetUsd} for LLM and replay cost together. Start by reading the scorecard.`,
183	        },
184	      ];
185	      messages.push(...start);
186	      log("start", { messages: start, config: { repo: opts.repo, budgetUsd: opts.budgetUsd, reviewId } });
